// ❌ OLD: Layout thrashing. Each iteration: the write to style.width
// dirties layout, then offsetWidth forces a synchronous reflow to
// answer the read. With N elements, that's N full (or subtree-wide)
// layouts — the classic jank source in resize/measure loops.
const els = document.querySelectorAll('.item');

for (const el of els) {
  // ❌ OLD: read — forces layout if dirty from the previous write
  const w = el.offsetWidth;
  el.style.width = `${w + 10}px`; // ❌ OLD: write — dirties layout again
}

// Each iteration reflows; total cost scales with N * layout-cost.

// ✅ NEW: Separate reads and writes. All geometry reads happen first
// (one layout flush, because the layout was clean), then all writes
// happen together (one dirty pass flushed later before paint).
const els = document.querySelectorAll('.item');

// ✅ NEW: Phase 1 — read everything (single synchronous layout)
const widths = [...els].map((el) => el.offsetWidth);

// ✅ NEW: Phase 2 — write everything (layout dirty once, flushed once)
els.forEach((el, i) => {
  el.style.width = `${widths[i] + 10}px`;
});

// Total: one forced layout for the reads, one batched layout for the
// writes — versus N forced layouts in the thrashing version.
